using Microsoft.Web.WebView2.Core;using Microsoft.Web.WebView2.WinForms;using System.Diagnostics;using System.Runtime.InteropServices;using System.Text.Json;namespace TVOS;public class LauncherForm:Form{readonly WebView2 w=new(){Dock=DockStyle.Fill};readonly ServiceManager sm=new();AppSettings set=new();RemoteServer? remote;System.Windows.Forms.Timer? watch;const int HOT=1001,WM=0x0312;const uint NOREPEAT=0x4000,HOME=0x24;[DllImport("user32.dll")]static extern bool RegisterHotKey(IntPtr h,int id,uint m,uint k);[DllImport("user32.dll")]static extern bool UnregisterHotKey(IntPtr h,int id);public LauncherForm(){Text="TVOS";FormBorderStyle=FormBorderStyle.None;WindowState=FormWindowState.Maximized;BackColor=Color.Black;Controls.Add(w);Shown+=ShownNow;FormClosed+=(_,_)=>{UnregisterHotKey(Handle,HOT);remote?.Dispose();};}protected override void OnHandleCreated(EventArgs e){base.OnHandleCreated(e);RegisterHotKey(Handle,HOT,NOREPEAT,HOME);}protected override void WndProc(ref Message m){if(m.Msg==WM&&m.WParam.ToInt32()==HOT){ReturnHome();return;}base.WndProc(ref m);}async void ShownNow(object?o,EventArgs e){try{set=sm.LoadSettings();Directory.CreateDirectory(AppPaths.WebView);var env=await CoreWebView2Environment.CreateAsync(null,AppPaths.WebView);await w.EnsureCoreWebView2Async(env);var s=w.CoreWebView2.Settings;s.AreDefaultContextMenusEnabled=false;s.AreDevToolsEnabled=false;s.IsStatusBarEnabled=false;s.AreBrowserAcceleratorKeysEnabled=false;w.CoreWebView2.WebMessageReceived+=Msg;w.Source=new Uri(AppPaths.Launcher);remote=new(set,sm,u=>BeginInvoke(()=>Launch(u)),()=>BeginInvoke(ReturnHome));remote.Start();}catch(Exception x){MessageBox.Show(x.ToString(),"TVOS startup error");}}void Msg(object?o,CoreWebView2WebMessageReceivedEventArgs e){try{using var d=JsonDocument.Parse(e.WebMessageAsJson);var r=d.RootElement;var a=r.TryGetProperty("action",out var z)?z.GetString():"";if(a=="getState")State();else if(a=="launch"&&r.TryGetProperty("url",out var u))Launch(u.GetString()??"");else if(a=="sleep")PowerManager.Sleep();else if(a=="remoteInfo")Send(new{type="remoteInfo",url=remote?.Url()??"Starting..."});}catch(Exception x){Send(new{type="error",message=x.Message});}}void State()=>Send(new{type="state",services=sm.Load().Services.Where(x=>x.Enabled).OrderBy(x=>x.Order),theme=ThemeManager.Resolve(set.Theme)});void Send(object o)=>w.CoreWebView2.PostWebMessageAsJson(JsonSerializer.Serialize(o));void Launch(string url){if(!Uri.TryCreate(url,UriKind.Absolute,out var u)||(u.Scheme!="https"&&u.Scheme!="http"))return;if(!File.Exists(set.ChromeExe)){MessageBox.Show("Chrome was not found:\n"+set.ChromeExe);return;}Hide();try{Process.Start(new ProcessStartInfo{FileName=set.ChromeExe,UseShellExecute=true,Arguments=$"--profile-directory=\"{set.ChromeProfile}\" --app=\"{url}\" --start-fullscreen --hide-scrollbars"});Watch();}catch(Exception x){ShowHome();MessageBox.Show(x.Message);}}void Watch(){watch?.Stop();watch=new(){Interval=1500};var grace=0;watch.Tick+=(_,_)=>{grace++;var v=Process.GetProcessesByName("chrome").Any(p=>{try{p.Refresh();return p.MainWindowHandle!=IntPtr.Zero;}catch{return false;}});if(grace>2&&!v){watch.Stop();ShowHome();}};watch.Start();}public void ReturnHome(){watch?.Stop();foreach(var p in Process.GetProcessesByName("chrome"))try{p.Refresh();if(p.MainWindowHandle!=IntPtr.Zero)p.CloseMainWindow();}catch{}ShowHome();}void ShowHome(){if(!Visible)Show();WindowState=FormWindowState.Maximized;BringToFront();Activate();w.Focus();State();}}